update public.exercises set consigne = '<p>C''est l''été et il fait très chaud. Vous voulez sortir avec votre fille de 8 ans. Vous choisissez une activité en fonction des critères suivants :</p><p>• dans un lieu frais, à l''abri du soleil ;<br>• accessible sans voiture ;<br>• adaptée aux enfants de son âge ;<br>• gratuite pour toute la famille.</p><p>Vous comparez ces quatre annonces. Pour chaque annonce, cochez (☒) OUI si cela correspond au critère ou NON si cela ne correspond pas.</p>', reading_text = null where id = 'lo22mvemyhx902j';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"lo22mvemyhx902jc1","titre":"Musée des Beaux-Arts","texte":"<p>Ses salles climatisées sont ouvertes jusqu''à 21 h en juillet et en août. Le musée se trouve à deux pas de la station de tramway Hôtel-de-Ville. Un livret-jeu permet aux enfants de 6 à 12 ans de découvrir les tableaux en s''amusant. Entrée gratuite pour les moins de 18 ans, 8 € pour les adultes. Un café avec terrasse ombragée accueille les visiteurs dans le jardin du musée.</p>"},{"id":"lo22mvemyhx902jc2","titre":"Baignade au lac de Vassy","texte":"<p>Plage surveillée de 11 h à 19 h. Le lac n''est desservi par aucun bus : un grand parking attend les visiteurs à l''entrée. Une zone peu profonde est réservée aux enfants. L''accès à la plage est gratuit. Attention : la plage n''a pas d''arbres, pensez à vos parasols. Les chiens ne sont pas acceptés sur la plage, même tenus en laisse.</p>"},{"id":"lo22mvemyhx902jc3","titre":"Grottes du Val-Noir","texte":"<p>13 °C toute l''année ! Visites guidées toutes les heures, de 10 h à 17 h. Une navette gratuite relie la gare aux grottes toutes les trente minutes. La visite, longue et difficile, est interdite aux enfants de moins de 10 ans. Tarif : 9 € par adulte. Prévoyez un pull et des chaussures fermées : le sol est humide et glissant.</p>"},{"id":"lo22mvemyhx902jc4","titre":"Atelier d''été de la médiathèque","texte":"<p>Tous les mercredis de juillet, de 14 h à 16 h, la médiathèque propose des lectures et des jeux pour les 6-10 ans dans sa salle climatisée. L''atelier est gratuit, mais il faut s''inscrire. La médiathèque est située en périphérie, loin des transports en commun : prévoyez votre voiture. Chaque séance se termine par un goûter offert par l''association des amis de la médiathèque.</p>"}],"criteres":[{"id":"lo22mvemyhx902jt1","texte":"Fraîcheur"},{"id":"lo22mvemyhx902jt2","texte":"Transport"},{"id":"lo22mvemyhx902jt3","texte":"Enfants"},{"id":"lo22mvemyhx902jt4","texte":"Prix"}]}'::jsonb, '{"answers":{"lo22mvemyhx902jt1_lo22mvemyhx902jc1":"OUI","lo22mvemyhx902jt2_lo22mvemyhx902jc1":"OUI","lo22mvemyhx902jt3_lo22mvemyhx902jc1":"OUI","lo22mvemyhx902jt4_lo22mvemyhx902jc1":"NON","lo22mvemyhx902jt1_lo22mvemyhx902jc2":"NON","lo22mvemyhx902jt2_lo22mvemyhx902jc2":"NON","lo22mvemyhx902jt3_lo22mvemyhx902jc2":"OUI","lo22mvemyhx902jt4_lo22mvemyhx902jc2":"OUI","lo22mvemyhx902jt1_lo22mvemyhx902jc3":"OUI","lo22mvemyhx902jt2_lo22mvemyhx902jc3":"OUI","lo22mvemyhx902jt3_lo22mvemyhx902jc3":"NON","lo22mvemyhx902jt4_lo22mvemyhx902jc3":"NON","lo22mvemyhx902jt1_lo22mvemyhx902jc4":"OUI","lo22mvemyhx902jt2_lo22mvemyhx902jc4":"NON","lo22mvemyhx902jt3_lo22mvemyhx902jc4":"OUI","lo22mvemyhx902jt4_lo22mvemyhx902jc4":"OUI"}}'::jsonb, 'Musée: « salles climatisées » (OUI), « à deux pas de la station de tramway » (OUI), « Un livret-jeu permet aux enfants de 6 à 12 ans » (OUI), « 8 € pour les adultes » (NON). Lac: « la plage n''a pas d''arbres » (NON), « n''est desservi par aucun bus » (NON), « Une zone peu profonde est réservée aux enfants » (OUI), « L''accès à la plage est gratuit » (OUI). Grottes: « 13 °C toute l''année » (OUI), « Une navette gratuite relie la gare aux grottes » (OUI), « interdite aux enfants de moins de 10 ans » (NON), « 9 € par adulte » (NON). Médiathèque: « sa salle climatisée » (OUI), « prévoyez votre voiture » (NON), « pour les 6-10 ans » (OUI), « L''atelier est gratuit » (OUI).')
